type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 760;
const CX = W / 2;

const COLORS = {
  input: { fill: '#e8f5e9', stroke: '#4caf50' },
  up: { fill: '#e3f2fd', stroke: '#1976d2' },
  activation: { fill: '#fce4ec', stroke: '#d81b60' },
  gate: { fill: '#ede9fe', stroke: '#7c3aed' },
  mul: { fill: '#fff3e0', stroke: '#f57c00' },
  down: { fill: '#fff8e1', stroke: '#f9a825' },
  output: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  weight: { fill: '#f1f5f9', stroke: '#64748b' },
  text: 'var(--text)',
  muted: 'var(--text-muted)',
};

const STEP_GROUPS = {
  input: 'step-mlp-input',
  up: 'step-mlp-up',
  activation: 'step-mlp-activation',
  gate: 'step-mlp-gate',
  gated: 'step-mlp-gated',
  down: 'step-mlp-down',
  output: 'step-mlp-output',
};

// Layout constants — very generous spacing so shapes/labels never overlap
const BOX_H = 72;
const BOX_W = 480;
const MAT_H = 64;
const VEC_H = 28;
const VEC_W = 126;
const WEIGHT_W = 110;
const SEQ_W = 140;
const GROUP_GAP = 48;          // gap between the bottom of one step group and the top of the next
const BOX_TO_ROW_GAP = 28;     // gap between a step box bottom and the matrix row top
const ROW_EQ_GAP = 50;         // gap between row center and the shape-equation label baseline
const ACT_PLOT_GAP = 24;       // gap between activation input vector bottom and plot top
const MUL_CIRCLE_GAP = 28;     // gap between multiply input vectors bottom and circle top
const PLOT_H = 120;
const PLOT_W = 280;

