// ═══════════════════════════════════════════════════════════════════════════════
// Low-level helpers
// ═══════════════════════════════════════════════════════════════════════════════

function lbl(
  g: Gsel,
  x: number,
  y: number,
  text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function arrowH(g: Gsel, x1: number, x2: number, y: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x1, y, x2, y, { color });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 14).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 2);
  lbl(g, cx, cy, text, { size: 12, weight: '700', color });
}

function roundBox(
  g: Gsel,
  cx: number,
  y: number,
  w: number,
  h: number,
  title: string,
  formula: string,
  fill: string,
  stroke: string
): number {
  const grp = g.append('g');
  grp
    .append('rect')
    .attr('x', cx - w / 2)
    .attr('y', y)
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 6)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);
  lbl(grp, cx, y + h / 2 - 11, title, { size: 14, weight: '600', color: 'var(--text)' });
  lbl(grp, cx, y + h / 2 + 12, formula, { size: 11, color: 'var(--text-muted)', font: 'monospace' });
  return y + h;
}

function stepBox(g: Gsel, cx: number, y: number, title: string, formula: string, fill: string, stroke: string): number {
  return roundBox(g, cx, y, BOX_W, BOX_H, title, formula, fill, stroke);
}

// ═══════════════════════════════════════════════════════════════════════════════
// Matrix helpers (all center-based)
// ═══════════════════════════════════════════════════════════════════════════════

function drawSeqMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.input.fill,
  stroke = COLORS.input.stroke
): void {
  drawMatrixBlock(g as Sel, x, cy - MAT_H / 2, {
    width: SEQ_W,
    height: MAT_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 5,
    dimTop: 'S',
    dimRight: 'D',
  });
}

function drawWeightMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.weight.fill,
  stroke = COLORS.weight.stroke
): void {
  drawMatrixBlock(g as Sel, x, cy - MAT_H / 2, {
    width: WEIGHT_W,
    height: MAT_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 5,
    rows: 5,
  });
}

function drawSmallVector(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill: string,
  stroke: string
): void {
  drawMatrixBlock(g as Sel, x, cy - VEC_H / 2, {
    width: VEC_W,
    height: VEC_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 1,
  });
}

function drawShapeEquation(g: Gsel, cx: number, cy: number, equation: string): void {
  lbl(g, cx, cy + ROW_EQ_GAP, equation, { size: 9, color: COLORS.muted, font: 'monospace' });
}

function drawMatmulRow(
  g: Gsel,
  cx: number,
  cy: number,
  leftLabel: string,
  leftShape: string,
  leftFill: string,
  leftStroke: string,
  weightLabel: string,
  weightShape: string,
  weightFill: string,
  weightStroke: string,
  rightLabel: string,
  rightShape: string,
  rightFill: string,
  rightStroke: string,
  equation: string
): number {
  const leftX = cx - 198;
  const weightX = cx - 66;
  const rightX = cx + 72;

  drawSmallVector(g, leftX, cy, leftLabel, leftShape, leftFill, leftStroke);
  drawWeightMatrix(g, weightX, cy, weightLabel, weightShape, weightFill, weightStroke);
  drawSmallVector(g, rightX, cy, rightLabel, rightShape, rightFill, rightStroke);

  arrowH(g, leftX + VEC_W, weightX, cy, leftStroke);
  arrowH(g, weightX + WEIGHT_W, rightX, cy, weightStroke);

  drawShapeEquation(g, cx, cy, equation);
  return cy + MAT_H / 2 + ROW_EQ_GAP + 8;
}

function drawActivationPlot(g: Gsel, cx: number, y: number, activation: string): number {
  const plotX = cx - PLOT_W / 2;
  const plotY = y;

  g.append('rect')
    .attr('x', plotX)
    .attr('y', plotY)
    .attr('width', PLOT_W)
    .attr('height', PLOT_H)
    .attr('rx', 4)
    .attr('fill', 'var(--surface)')
    .attr('stroke', 'var(--border)');

  let fn: (x: number) => number;
  switch (activation) {
    case 'relu':
      fn = (x) => Math.max(0, x);
      break;
    case 'silu':
      fn = (x) => x / (1 + Math.exp(-x));
      break;
    case 'sigmoid':
      fn = (x) => 1 / (1 + Math.exp(-x));
      break;
    case 'gelu':
    default:
      fn = (x) => (x * (1 + Math.tanh(Math.sqrt(2 / Math.PI) * (x + 0.044715 * x ** 3)))) / 2;
      break;
  }

  const points: [number, number][] = [];
  for (let i = 0; i <= 50; i++) {
    const xv = (i / 50) * 6 - 3;
    const yv = fn(xv);
    const px = plotX + 12 + (i / 50) * (PLOT_W - 24);
    const py = plotY + PLOT_H - 12 - ((yv + 1) / 4.5) * (PLOT_H - 24);
    points.push([px, py]);
  }

  const line = d3.line<[number, number]>().x((d) => d[0]).y((d) => d[1]);
  g.append('path')
    .datum(points)
    .attr('d', line)
    .attr('fill', 'none')
    .attr('stroke', COLORS.activation.stroke)
    .attr('stroke-width', 2);

  // Axes
  g.append('line')
    .attr('x1', plotX + 12)
    .attr('y1', plotY + PLOT_H / 2)
    .attr('x2', plotX + PLOT_W - 12)
    .attr('y2', plotY + PLOT_H / 2)
    .attr('stroke', 'var(--border)')
    .attr('stroke-width', 1);
  g.append('line')
    .attr('x1', plotX + PLOT_W / 2)
    .attr('y1', plotY + 12)
    .attr('x2', plotX + PLOT_W / 2)
    .attr('y2', plotY + PLOT_H - 12)
    .attr('stroke', 'var(--border)')
    .attr('stroke-width', 1);

  // Axis labels
  lbl(g, plotX + PLOT_W - 10, plotY + PLOT_H / 2 + 12, 'h', { size: 10, color: COLORS.muted, anchor: 'end' });
  lbl(g, plotX + PLOT_W / 2 - 8, plotY + 16, 'σ(h)', { size: 10, color: COLORS.muted, anchor: 'end' });

  lbl(g, cx, plotY + PLOT_H + 16, `${activation.toUpperCase()} curve`, { size: 10, color: COLORS.muted });
  return plotY + PLOT_H + 36;
}

function drawElementWise(
  g: Gsel,
  cx: number,
  cy: number,
  leftLabel: string,
  rightLabel: string,
  outLabel: string,
  op: string,
  equation: string,
  leftFill: string,
  leftStroke: string,
  rightFill: string,
  rightStroke: string,
  outFill: string,
  outStroke: string
): number {
  const leftX = cx - 198;
  const rightX = cx + 72;
  const circleCy = cy + VEC_H / 2 + MUL_CIRCLE_GAP + 16;
  const outCy = cy + 110;

  drawSmallVector(g, leftX, cy, leftLabel, '[B, S, d_ff]', leftFill, leftStroke);
  drawSmallVector(g, rightX, cy, rightLabel, '[B, S, d_ff]', rightFill, rightStroke);

  drawArrow(g as Sel, leftX + VEC_W, cy, cx, circleCy, { color: leftStroke });
  drawArrow(g as Sel, rightX, cy, cx, circleCy, { color: rightStroke });

  opCircle(g, cx, circleCy, op, COLORS.mul.stroke);
  arrowDown(g, cx, circleCy + 14, outCy - VEC_H / 2, COLORS.mul.stroke);
  drawSmallVector(g, cx - VEC_W / 2, outCy, outLabel, '[B, S, d_ff]', outFill, outStroke);

  lbl(g, cx, outCy + 26, equation, { size: 10, color: COLORS.muted, font: 'monospace' });
  return outCy + 52;
}

function drawParamSummary(g: Gsel, cx: number, y: number, dModel: number, dFf: number, variant: string): number {
  const SUM_W = 470;
  const grp = g.append('g').attr('transform', `translate(${cx - SUM_W / 2}, ${y})`);
  grp.append('rect').attr('width', SUM_W).attr('height', 48).attr('rx', 6)
    .attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 1);
  lbl(grp, 8, 14, 'Parameters →', { size: 8, weight: '700', color: 'var(--text-muted)' });

  const items = [
    { label: `d_model = ${dModel}`, dim: 'input/output dim', color: '#4caf50' },
    { label: `d_ff = ${dFf}`, dim: 'FFN width', color: '#1976d2' },
    { label: `variant = ${variant.replace(/_/g, '-')}`, dim: 'architecture', color: '#7c3aed' },
  ];
  items.forEach((item, i) => {
    const px = 10 + i * 155;
    grp.append('rect').attr('x', px).attr('y', 22).attr('width', 150).attr('height', 18).attr('rx', 4)
      .attr('fill', hexWithAlpha(item.color, 0.08)).attr('stroke', item.color).attr('stroke-width', 1);
    lbl(grp, px + 6, 31, item.label, { size: 7, weight: '600', color: item.color, font: 'monospace', anchor: 'start' });
    lbl(grp, px + 6, 38, `→ ${item.dim}`, { size: 6, color: item.color, anchor: 'start' });
  });
  return y + 56;
}

function hexWithAlpha(hex: string, alpha: number): string {
  const v = hex.replace('#', '');
  const bigint = parseInt(v, 16);
  const r = (bigint >> 16) & 255;
  const g = (bigint >> 8) & 255;
  const b = bigint & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Variant renderers
// ═══════════════════════════════════════════════════════════════════════════════

interface RenderResult {
  steps: MlpStep[];
  y: number;
}

function startGroup(_g: Gsel, className: string, step: number): Gsel {
  return _g.append('g').attr('class', `step-node ${className}`).attr('data-step', String(step));
}

function renderStandard(_g: Gsel, cx: number, y: number, activation: string): RenderResult {
  const steps: MlpStep[] = [];

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = startGroup(_g, STEP_GROUPS.input, 1);
  const inCy = y + MAT_H / 2;
  drawSeqMatrix(inputGrp, cx - 70, inCy, 'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke);
  y = inCy + MAT_H / 2 + GROUP_GAP;

  // 2. Up-project
  steps.push({ ...BASE_STEPS.up, id: 2 });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.up.stroke);
  const upGrp = startGroup(_g, STEP_GROUPS.up, 2);
  const upBoxBottom = stepBox(upGrp, cx, y, 'Up-project to d_ff', 'h = x · W_up', COLORS.up.fill, COLORS.up.stroke);
  const upRowCy = upBoxBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  const upBottom = drawMatmulRow(
    upGrp, cx, upRowCy,
    'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke,
    'W_up', '[D, d_ff]', COLORS.weight.fill, COLORS.weight.stroke,
    'h', '[B, S, d_ff]', COLORS.up.fill, COLORS.up.stroke,
    '[B, S, D] @ [D, d_ff] → [B, S, d_ff]'
  );
  y = upBottom + GROUP_GAP;

  // 3. Activation
  steps.push({
    ...BASE_STEPS.activation,
    id: 3,
    label: `${activation.toUpperCase()} Activation`,
    formula: `a = ${activation}(h)`,
    explanation: `Applies ${activation.toUpperCase()} element-wise to every value in h.`,
    code: { title: 'Activation', lines: [`a = F.${activation}(h)  # [B, S, d_ff]`] },
  });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.activation.stroke);
  const actGrp = startGroup(_g, STEP_GROUPS.activation, 3);
  const actBoxBottom = stepBox(actGrp, cx, y, `${activation.toUpperCase()} Activation`, `a = ${activation}(h)`, COLORS.activation.fill, COLORS.activation.stroke);
  const actVecCy = actBoxBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  drawSmallVector(actGrp, cx - 63, actVecCy, 'h', '[B, S, d_ff]', COLORS.up.fill, COLORS.up.stroke);
  arrowDown(actGrp, cx, actVecCy + VEC_H / 2, actVecCy + VEC_H / 2 + ACT_PLOT_GAP, COLORS.activation.stroke);
  const actPlotBottom = drawActivationPlot(actGrp, cx, actVecCy + VEC_H / 2 + ACT_PLOT_GAP, activation);
  y = actPlotBottom + GROUP_GAP;

  // 4. Down-project
  steps.push({
    ...BASE_STEPS.down,
    id: 4,
    formula: 'out = a · W_down',
    code: {
      title: 'Down-Projection',
      lines: [
        'self.W_down = nn.Linear(d_ff, d_model)',
        'out = self.W_down(a)  # [B, S, D]',
      ],
    },
  });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.down.stroke);
  const downGrp = startGroup(_g, STEP_GROUPS.down, 4);
  const downBoxBottom = stepBox(downGrp, cx, y, 'Down-project to d_model', 'out = a · W_down', COLORS.down.fill, COLORS.down.stroke);
  const downRowCy = downBoxBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  const downBottom = drawMatmulRow(
    downGrp, cx, downRowCy,
    'a', '[B, S, d_ff]', COLORS.activation.fill, COLORS.activation.stroke,
    'W_down', '[d_ff, D]', COLORS.weight.fill, COLORS.weight.stroke,
    'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke,
    '[B, S, d_ff] @ [d_ff, D] → [B, S, D]'
  );
  y = downBottom + GROUP_GAP;

  // 5. Output
  steps.push({ ...BASE_STEPS.output, id: 5 });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.output.stroke);
  const outGrp = startGroup(_g, STEP_GROUPS.output, 5);
  const outCy = y + MAT_H / 2;
  drawSeqMatrix(outGrp, cx - 70, outCy, 'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke);
  y = outCy + MAT_H / 2 + GROUP_GAP;

  return { steps, y };
}

function renderGated(
  _g: Gsel,
  cx: number,
  y: number,
  variant: string,
  gateActivation: string
): RenderResult {
  const steps: MlpStep[] = [];
  const variantLabel = variant.replace(/_/g, '-').toUpperCase();
  const gateActLower = gateActivation.toLowerCase();

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = startGroup(_g, STEP_GROUPS.input, 1);
  const inCy = y + MAT_H / 2;
  drawSeqMatrix(inputGrp, cx - 60, inCy, 'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke);
  y = inCy + MAT_H / 2 + GROUP_GAP;

  // 2. Gate + Up (parallel)
  steps.push({
    ...BASE_STEPS.gate,
    id: 2,
    label: `${variantLabel}: gate & up`,
    formula: `gate = x·W_gate,  up = x·W_up`,
    explanation:
      `${variantLabel} runs two linear projections from x in parallel. ` +
      `The gate branch will be activated and multiplied element-wise with the up branch.`,
    code: {
      title: `${variantLabel} gate & up`,
      lines: [
        'self.W_gate = nn.Linear(d_model, d_ff)',
        'self.W_up = nn.Linear(d_model, d_ff)',
        `gate = self.W_gate(x)  # [B, S, d_ff]`,
        `up = self.W_up(x)      # [B, S, d_ff]`,
      ],
    },
  });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.gate.stroke);
  const gateGrp = startGroup(_g, STEP_GROUPS.gate, 2);
  const gateBoxBottom = stepBox(gateGrp, cx, y, `${variantLabel}: gate & up`, 'gate = x·W_gate, up = x·W_up', COLORS.gate.fill, COLORS.gate.stroke);

  const splitCy = gateBoxBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  drawSmallVector(gateGrp, cx - 63, splitCy, 'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke);
  arrowDown(gateGrp, cx, splitCy + VEC_H / 2, splitCy + VEC_H / 2 + MUL_CIRCLE_GAP, COLORS.gate.stroke);
  opCircle(gateGrp, cx, splitCy + VEC_H / 2 + MUL_CIRCLE_GAP + 16, '×2', COLORS.gate.stroke);
  lbl(gateGrp, cx + 22, splitCy + VEC_H / 2 + MUL_CIRCLE_GAP + 16, 'split to both branches', { size: 9, color: COLORS.muted, anchor: 'start' });

  const branchStartCy = splitCy + VEC_H / 2 + MUL_CIRCLE_GAP + 16 + 34;

  // Gate branch
  const gateBranchCy = branchStartCy;
  const gateBranchBottom = drawMatmulRow(
    gateGrp, cx, gateBranchCy,
    'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke,
    'W_gate', '[D, d_ff]', COLORS.gate.fill, COLORS.gate.stroke,
    'gate', '[B, S, d_ff]', COLORS.gate.fill, COLORS.gate.stroke,
    '[B, S, D] @ [D, d_ff] → [B, S, d_ff]'
  );
  lbl(gateGrp, cx + 212, gateBranchCy, 'Gate branch', { size: 9, color: COLORS.gate.stroke, anchor: 'start' });

  // Up branch
  const upBranchCy = gateBranchCy + 108;
  const upBranchBottom = drawMatmulRow(
    gateGrp, cx, upBranchCy,
    'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke,
    'W_up', '[D, d_ff]', COLORS.up.fill, COLORS.up.stroke,
    'up', '[B, S, d_ff]', COLORS.up.fill, COLORS.up.stroke,
    '[B, S, D] @ [D, d_ff] → [B, S, d_ff]'
  );
  lbl(gateGrp, cx + 212, upBranchCy, 'Up branch', { size: 9, color: COLORS.up.stroke, anchor: 'start' });

  y = Math.max(gateBranchBottom, upBranchBottom) + GROUP_GAP;

  // 3. Gate activation
  steps.push({
    ...BASE_STEPS.activation,
    id: 3,
    label: `${gateActivation} gate activation`,
    shortLabel: 'Gate Act',
    formula: `gate_act = ${gateActivation}(gate)`,
    explanation: `The gate branch is activated with ${gateActivation}. The up branch is left linear.`,
    code: { title: 'Gate activation', lines: [`gate_act = F.${gateActLower}(gate)  # [B, S, d_ff]`] },
    svgGroup: STEP_GROUPS.activation,
    color: COLORS.activation.stroke,
    fill: COLORS.activation.fill,
  });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.activation.stroke);
  const actGrp = startGroup(_g, STEP_GROUPS.activation, 3);
  const actBoxBottom = stepBox(actGrp, cx, y, `${gateActivation} gate activation`, `gate_act = ${gateActivation}(gate)`, COLORS.activation.fill, COLORS.activation.stroke);
  const actVecCy = actBoxBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  drawSmallVector(actGrp, cx - 63, actVecCy, 'gate', '[B, S, d_ff]', COLORS.gate.fill, COLORS.gate.stroke);
  arrowDown(actGrp, cx, actVecCy + VEC_H / 2, actVecCy + VEC_H / 2 + ACT_PLOT_GAP, COLORS.activation.stroke);
  const actPlotBottom = drawActivationPlot(actGrp, cx, actVecCy + VEC_H / 2 + ACT_PLOT_GAP, gateActLower);
  y = actPlotBottom + GROUP_GAP;

  // 4. Element-wise multiply
  steps.push({
    ...BASE_STEPS.gated,
    id: 4,
    label: `${variantLabel} gating`,
    formula: 'gated = gate_act ⊗ up',
    explanation:
      'The activated gate is multiplied element-wise with the up projection. ' +
      'This is the core of GLU-style FFNs; it replaces a separate activation after the up-project.',
    code: { title: 'Element-wise gating', lines: ['gated = gate_act * up  # [B, S, d_ff]'] },
  });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.mul.stroke);
  const mulGrp = startGroup(_g, STEP_GROUPS.gated, 4);
  const mulBoxBottom = stepBox(mulGrp, cx, y, `${variantLabel} gating`, 'gated = gate_act ⊗ up', COLORS.mul.fill, COLORS.mul.stroke);
  const mulVecCy = mulBoxBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  const mulBottom = drawElementWise(
    mulGrp, cx, mulVecCy,
    'gate_act', 'up', 'gated', '⊗', 'gated = gate_act ⊗ up  [B, S, d_ff]',
    COLORS.activation.fill, COLORS.activation.stroke,
    COLORS.up.fill, COLORS.up.stroke,
    COLORS.mul.fill, COLORS.mul.stroke
  );
  y = mulBottom + GROUP_GAP;

  // 5. Down-project
  steps.push({ ...BASE_STEPS.down, id: 5 });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.down.stroke);
  const downGrp = startGroup(_g, STEP_GROUPS.down, 5);
  const downBoxBottom = stepBox(downGrp, cx, y, 'Down-project to d_model', 'out = gated · W_down', COLORS.down.fill, COLORS.down.stroke);
  const downRowCy = downBoxBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  const downBottom = drawMatmulRow(
    downGrp, cx, downRowCy,
    'gated', '[B, S, d_ff]', COLORS.mul.fill, COLORS.mul.stroke,
    'W_down', '[d_ff, D]', COLORS.weight.fill, COLORS.weight.stroke,
    'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke,
    '[B, S, d_ff] @ [d_ff, D] → [B, S, D]'
  );
  y = downBottom + GROUP_GAP;

  // 6. Output
  steps.push({ ...BASE_STEPS.output, id: 6 });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.output.stroke);
  const outGrp = startGroup(_g, STEP_GROUPS.output, 6);
  const outCy = y + MAT_H / 2;
  drawSeqMatrix(outGrp, cx - 70, outCy, 'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke);
  y = outCy + MAT_H / 2 + GROUP_GAP;

  return { steps, y };
}

function renderSquaredRelu(_g: Gsel, cx: number, y: number): RenderResult {
  const steps: MlpStep[] = [];

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = startGroup(_g, STEP_GROUPS.input, 1);
  const inCy = y + MAT_H / 2;
  drawSeqMatrix(inputGrp, cx - 70, inCy, 'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke);
  y = inCy + MAT_H / 2 + GROUP_GAP;

  // 2. Up-project
  steps.push({ ...BASE_STEPS.up, id: 2 });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.up.stroke);
  const upGrp = startGroup(_g, STEP_GROUPS.up, 2);
  const upBoxBottom = stepBox(upGrp, cx, y, 'Up-project to d_ff', 'h = x · W_up', COLORS.up.fill, COLORS.up.stroke);
  const upRowCy = upBoxBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  const upBottom = drawMatmulRow(
    upGrp, cx, upRowCy,
    'x', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke,
    'W_up', '[D, d_ff]', COLORS.weight.fill, COLORS.weight.stroke,
    'h', '[B, S, d_ff]', COLORS.up.fill, COLORS.up.stroke,
    '[B, S, D] @ [D, d_ff] → [B, S, d_ff]'
  );
  y = upBottom + GROUP_GAP;

  // 3. ReLU activation
  steps.push({
    ...BASE_STEPS.activation,
    id: 3,
    label: 'ReLU Activation',
    formula: 'a = ReLU(h)',
    explanation: 'Negative values are clipped to zero; positive values pass through unchanged.',
    code: { title: 'ReLU', lines: ['a = F.relu(h)  # [B, S, d_ff]'] },
  });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.activation.stroke);
  const actGrp = startGroup(_g, STEP_GROUPS.activation, 3);
  const actBoxBottom = stepBox(actGrp, cx, y, 'ReLU Activation', 'a = ReLU(h)', COLORS.activation.fill, COLORS.activation.stroke);
  const actVecCy = actBoxBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  drawSmallVector(actGrp, cx - 63, actVecCy, 'h', '[B, S, d_ff]', COLORS.up.fill, COLORS.up.stroke);
  arrowDown(actGrp, cx, actVecCy + VEC_H / 2, actVecCy + VEC_H / 2 + ACT_PLOT_GAP, COLORS.activation.stroke);
  const actPlotBottom = drawActivationPlot(actGrp, cx, actVecCy + VEC_H / 2 + ACT_PLOT_GAP, 'relu');
  y = actPlotBottom + GROUP_GAP;

  // 4. Square
  steps.push({
    ...BASE_STEPS.square,
    id: 4,
    label: 'Square activation',
    shortLabel: 'Square',
    formula: 'sq = a²',
    explanation:
      'Each activated value is squared. This produces a smooth non-linearity that is zero for negative inputs and quadratic for positive inputs.',
    code: { title: 'Square', lines: ['sq = a * a  # [B, S, d_ff]'] },
  });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.mul.stroke);
  const mulGrp = startGroup(_g, STEP_GROUPS.gated, 4);
  const mulBoxBottom = stepBox(mulGrp, cx, y, 'Square activation', 'sq = a ⊗ a', COLORS.mul.fill, COLORS.mul.stroke);
  const mulVecCy = mulBoxBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  const mulBottom = drawElementWise(
    mulGrp, cx, mulVecCy,
    'a', 'a', 'sq', '⊗', 'sq = a ⊗ a  [B, S, d_ff]',
    COLORS.activation.fill, COLORS.activation.stroke,
    COLORS.activation.fill, COLORS.activation.stroke,
    COLORS.mul.fill, COLORS.mul.stroke
  );
  y = mulBottom + GROUP_GAP;

  // 5. Down-project
  steps.push({
    ...BASE_STEPS.down,
    id: 5,
    formula: 'out = sq · W_down',
    code: {
      title: 'Down-Projection',
      lines: [
        'self.W_down = nn.Linear(d_ff, d_model)',
        'out = self.W_down(sq)  # [B, S, D]',
      ],
    },
  });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.down.stroke);
  const downGrp = startGroup(_g, STEP_GROUPS.down, 5);
  const downBoxBottom = stepBox(downGrp, cx, y, 'Down-project to d_model', 'out = sq · W_down', COLORS.down.fill, COLORS.down.stroke);
  const downRowCy = downBoxBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  const downBottom = drawMatmulRow(
    downGrp, cx, downRowCy,
    'sq', '[B, S, d_ff]', COLORS.mul.fill, COLORS.mul.stroke,
    'W_down', '[d_ff, D]', COLORS.weight.fill, COLORS.weight.stroke,
    'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke,
    '[B, S, d_ff] @ [d_ff, D] → [B, S, D]'
  );
  y = downBottom + GROUP_GAP;

  // 6. Output
  steps.push({ ...BASE_STEPS.output, id: 6 });
  arrowDown(_g, cx, y - GROUP_GAP, y, COLORS.output.stroke);
  const outGrp = startGroup(_g, STEP_GROUPS.output, 6);
  const outCy = y + MAT_H / 2;
  drawSeqMatrix(outGrp, cx - 70, outCy, 'out', '[B, S, D]', COLORS.output.fill, COLORS.output.stroke);
  y = outCy + MAT_H / 2 + GROUP_GAP;

  return { steps, y };
}

