export function renderMlpDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: import('../../components/types').ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 512;
  const dFf = Number(params.d_ff) || 2048;
  const variant = String(params.mlp_variant || 'standard');
  const activation = String(params.activation || 'gelu');

  const dModelSel = g as unknown as Gsel;
  let y = 28;

  // Title
  lbl(dModelSel, CX, y, 'Feed-Forward Network (MLP)', { size: 15, weight: '700', color: COLORS.text });
  y += 18;
  lbl(dModelSel, CX, y, `d_model=${dModel}  d_ff=${dFf}  variant=${variant.replace(/_/g, '-')}`, {
    size: 10,
    color: COLORS.muted,
  });
  y += 22;

  // Param summary
  y = drawParamSummary(dModelSel, CX, y, dModel, dFf, variant);
  y += 16;

  // Variant-specific diagram
  let result: RenderResult;
  switch (variant) {
    case 'swiglu':
      result = renderGated(dModelSel, CX, y, 'swiglu', 'SiLU');
      break;
    case 'geglu':
      result = renderGated(dModelSel, CX, y, 'geglu', 'GELU');
      break;
    case 'reglu':
      result = renderGated(dModelSel, CX, y, 'reglu', 'ReLU');
      break;
    case 'glu':
      result = renderGated(dModelSel, CX, y, 'glu', 'Sigmoid');
      break;
    case 'squared_relu':
      result = renderSquaredRelu(dModelSel, CX, y);
      break;
    case 'standard':
    default:
      result = renderStandard(dModelSel, CX, y, activation);
      break;
  }

  // Footer summary
  const isTwoMatrix = variant === 'squared_relu' || variant === 'standard';
  const totalParams = isTwoMatrix ? dModel * dFf * 2 : dModel * dFf * 3;
  const flopsPerToken = isTwoMatrix ? 4 * dModel * dFf : 6 * dModel * dFf;
  const summaryGrp = dModelSel.append('g');
  lbl(summaryGrp, CX, result.y + 14, `≈ ${fmtNum(totalParams)} params (${isTwoMatrix ? 2 : 3} weight matrices) · ~${fmtNum(flopsPerToken)} FLOP/token`, {
    size: 9,
    color: COLORS.muted,
  });
  result.y += 32;

  // Explanations
  result.y = drawExplanation(
    g,
    80,
    result.y,
    W - 160,
    'The MLP expands the hidden dimension to create capacity for non-linear transformations. ' +
      'Gated variants (SwiGLU, GeGLU, ReGLU, GLU) use three matrices and an element-wise gate, ' +
      'often improving quality over the classic two-matrix design.',
    'insight'
  );
  result.y += 10;

  result.y = drawExplanation(
    g,
    80,
    result.y,
    W - 160,
    `FLOPs per token: ${fmtNum(flopsPerToken)}. ` +
      'The up/down projections dominate cost; gated variants add ~50% more FLOPs but usually require fewer d_ff parameters to match quality.',
    'perf'
  );
  result.y += 10;

  // Cross-link
  drawComponentLink(g, CX - 70, result.y, 140, 24, 'transformer-block', 'View Transformer Block ↗', {
    fill: '#e3f2fd',
    stroke: '#1976d2',
  });
  result.y += 40;

  // Code annotation
  const codeLines = buildCodeLines(variant, activation, dModel, dFf);
  result.y = drawCodeAnnotation(
    g,
    80,
    result.y,
    W - 160,
    `Feed-Forward Network — ${variant.replace(/_/g, '-').toUpperCase()}`,
    [`Params: ${fmtNum(totalParams)}. FLOPs per token: ${fmtNum(flopsPerToken)}.`],
    codeLines
  );

  return { width: W, height: result.y + 20, steps: result.steps };
}

function buildCodeLines(variant: string, activation: string, dModel: number, dFf: number): string[] {
  switch (variant) {
    case 'swiglu':
    case 'geglu':
    case 'reglu':
    case 'glu': {
      const gateAct = variant === 'swiglu' ? 'silu' : variant === 'geglu' ? 'gelu' : variant === 'reglu' ? 'relu' : 'sigmoid';
      return [
        `self.W_gate = nn.Linear(${dModel}, ${dFf})`,
        `self.W_up = nn.Linear(${dModel}, ${dFf})`,
        `self.W_down = nn.Linear(${dFf}, ${dModel})`,
        '',
        'def forward(self, x):',
        '    gate = self.W_gate(x)',
        `    gate = F.${gateAct}(gate)`,
        '    up = self.W_up(x)',
        '    gated = gate * up',
        '    return self.W_down(gated)',
      ];
    }
    case 'squared_relu':
      return [
        `self.W_up = nn.Linear(${dModel}, ${dFf})`,
        `self.W_down = nn.Linear(${dFf}, ${dModel})`,
        '',
        'def forward(self, x):',
        '    h = self.W_up(x)',
        '    a = F.relu(h)',
        '    sq = a * a',
        '    return self.W_down(sq)',
      ];
    case 'standard':
    default:
      return [
        `self.W_up = nn.Linear(${dModel}, ${dFf})`,
        `self.W_down = nn.Linear(${dFf}, ${dModel})`,
        '',
        'def forward(self, x):',
        '    h = self.W_up(x)',
        `    a = F.${activation}(h)`,
        '    return self.W_down(a)',
      ];
  }
}
